CREATE TEMP TABLE prompt_specs (
  ord serial,
  category text,
  title text,
  description text,
  goal text,
  deliverables text[]
);


SELECT
  regexp_replace(lower(s.title), '[^a-z0-9]+', '-', 'g') || '-' || s.category,
  s.title,
  s.category,
  s.description,
  'You are a senior ' ||
    CASE s.category
      WHEN 'marketing' THEN 'marketing strategist'
      WHEN 'social-media' THEN 'social media strategist and copywriter'
      WHEN 'grants-funding' THEN 'grant writer and funding consultant'
      WHEN 'business-planning' THEN 'business planning consultant'
      WHEN 'professional-emails' THEN 'business communication specialist'
      WHEN 'resumes-career' THEN 'career coach and professional resume writer'
      ELSE 'productivity and operations consultant'
    END ||
  ' working with the founder of [BUSINESS NAME], a [INDUSTRY] business serving [TARGET AUDIENCE].' || E'\n\n' ||
  'GOAL' || E'\n' || s.goal || E'\n\n' ||
  'MY DETAILS' || E'\n' ||
  '- Business name: [BUSINESS NAME]' || E'\n' ||
  '- Industry: [INDUSTRY]' || E'\n' ||
  '- Target audience: [TARGET AUDIENCE]' || E'\n' ||
  '- Main offer: [PRODUCT]' || E'\n' ||
  '- What I want most right now: [GOAL]' || E'\n\n' ||
  'WHAT TO PRODUCE' || E'\n' ||
  (SELECT string_agg('- ' || d, E'\n') FROM unnest(s.deliverables) AS d) || E'\n\n' ||
  'HOW TO WORK' || E'\n' ||
  '1. Do not ask me questions before you begin. Make sensible assumptions and label them clearly at the end.' || E'\n' ||
  '2. Write in a warm, confident, professional voice suited to a woman-owned business.' || E'\n' ||
  '3. Be specific and usable: real numbers, examples and wording I can act on today, never vague filler.' || E'\n' ||
  '4. Use clear headings, short paragraphs, and tables or numbered lists where they make the work easier to follow.' || E'\n' ||
  '5. Finish with a "Next 3 actions" list and one question that would make the result even stronger.' ||
  CASE WHEN s.category = 'grants-funding'
    THEN E'\n\n' || 'NOTE: This prompt offers educational and writing assistance only. It does not guarantee funding or grant approval.'
    ELSE '' END,
  s.ord,
  s.ord % 8 = 1,
  true
FROM prompt_specs s;

DROP TABLE prompt_specs;